window.kbPageData["views/entry/k-3ca54ae4271964df"] = {"key":"entry/k-3ca54ae4271964df","state":{"route":"entry/k-3ca54ae4271964df"},"node":{"id":"k-3ca54ae4271964df","mode":"k","title":"整数约束下的取整","type":"方法与技能","domain":"数学","reading":"","intro":"","priority":100,"aliases":["整数数量约束的取整规则"],"qs":["国考 2023 副省级 行测#63"],"current":false,"candidates":true,"sources":[],"basisGroup":"","authority":null,"sourceOnly":false,"reviewSet":"单次条目","independentCount":1,"repeatPositions":0,"directorySummary":"数量必须为整数时，先列不等式，再取满足条件的最小或最大整数。对严格下限，最小可行整数是下界向下取整后加1；对含等号的上限，最大可行整数是上界向下取整。","review":{"definition":"数量必须为整数时，先列不等式，再取满足条件的最小或最大整数。对严格下限，最小可行整数是下界向下取整后加1；对含等号的上限，最大可行整数是上界向下取整。","explanation":"只有乙设备消耗C零件，每台用9个，因此乙的台数必须大于100÷9，最少为12。每增加1台乙设备都会多用13个零件，取12台可为甲留下最多的零件。12台乙用掉156个，最多剩44个，而每台甲用16个，所以甲最多生产2台。生产12台乙和2台甲共用188个零件，其中C零件用108个，满足两项约束。","references":[],"evidence":"则乙设备数量最少为11+1=12个","disposition":"练习技能","basis":"据原题和解析编释。"}},"questions":{"国考 2023 副省级 行测#63":{"paper":"国考 2023 副省级 行测","n":63,"mod":"数量关系","src":["503793642e845de9795f.pdf",11],"asrc":["ecade1ff5af69283232e.pdf",19],"card":"bc0e8ddc88ab6a0aa976e6a2","links":[{"id":"k-3ca54ae4271964df","role":"解题依据","why":"把严格下限换算为满足条件的最小整数，并把总量上限换算为最大可行整数。"}]}},"terms":{},"references":{},"topics":[],"units":{"k-3ca54ae4271964df":[["国考 2023 副省级 行测#63"]]}};
